<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateChannelVO;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;

trait TemplateChannelAttributeHolder
{
  protected TemplateChannelVO|TemplateChannelOptions|null $channel = null;
  protected bool $channelAssigned = false;

  public function getChannelOrDefault(TemplateChannelVO $channel): TemplateChannelVO
  {
  if( $this->channelAssigned ) {
    \assert( null !== $this->channel );
    return TemplateChannelVO::from($this->channel);
  } else {
    return $channel;
  }
  }
  public function channel(TemplateChannelVO|TemplateChannelOptions $channel): static
  {
    $this->channel = $channel;
    $this->channelAssigned = true;
    return $this;
  }
  public function getChannel(): ?TemplateChannelOptions
  {
    return $this->channel instanceof TemplateChannelVO ? $this->channel->value() : $this->channel;
  }
  public function isChannelAssigned(): bool
  {
    return $this->channelAssigned;
  }
  public function writeChannelTo(mixed $att): void
  {
    if ($this->channelAssigned) {
      \assert(null !== $this->channel);
      $att->channel($this->channel);
    }  }
  public function readChannelFrom(mixed $att): void
  {
    if ($att->isChannelAssigned() ) {
      $channel = $att->getChannel();
      \assert(null !== $channel);
      $this->channel($channel);
    }
  }
  public function unsetChannel(): static
  {
    $this->channelAssigned = false;
    return $this;
  }
  protected function withDefaultChannel(): void   
  {
  }
  protected function withAssertedChannelRules(self $value, ConstraintFailList $errorsList): void  
  {
    if ($value->channelAssigned = $this->channelAssigned) {
      $value->channel = TemplateChannelVO::tryFrom($this->channel, $errorsList);
    }
  }
}
